messages.content:
Generate an AI-authored simulation-only serial mock for the attached trusted
SPI driver harness. This is the tb_driver target: it validates the harness's bit
ordering, CS framing, and scoreboard. It cannot establish that a recovered
cryptographic circuit works. Do not implement AES or any crypto transformation.
Do not modify the harness, shared operations, or a recovered DUT.

Return exactly one JSON object with string fields mock_sv and
scheduling_explanation. The module must be named spi_mock_peripheral with inputs
SCK, RST_N, MOSI, NORM_CS_N, START, ENC_DEC, and [31:0] RESPONSE_WORD; outputs
MISO, BUSY, ICE_LED, [31:0] RECEIVED_WORD, [31:0] FRAME_COUNT, [31:0] FRAME_BITS.

RESPONSE_WORD is test-only configuration latched at CS assertion, independent of
MOSI. Shift its MSB onto registered MISO at each selected rising SCK. Shift MOSI
MSB first into RECEIVED_WORD. Require exactly 32 rising edges per uninterrupted
CS-low frame; reject short, split, and overlong selections. CS changes must occur
while SCK is low. Count completed frames at CS release. Ignore serial traffic
while CS is high. Apply synchronous active-low reset on a rising SCK. A START
pulse outside selection sets BUSY, and exactly three additional SCK rising edges
clear BUSY. This latency is an arbitrary mock rule, not a claim about hardware.

The harness uses deterministic timing and seed 4313 by default, with a fixed LCG
and bounded runs. Preserve one consistent source of SCK transitions in
spi_operations.svh. Do not drive SCK or introduce a mock clock. Timeouts must
bound every potentially unbounded wait; the mock should contain no waits.
Treat X/Z control or comparison values as failures. Emit clear DRIVER FAIL
names and nonzero simulator exits for framing faults. The harness emits named
pass/fail results and waveforms; do not add file access or system commands.

Explain drive/sample scheduling: controls and MOSI change while SCK is low,
inputs have a half-period setup interval, registered MISO settles through NBA,
and the harness samples after a 1 ns delay. State how the separate CS monitor
settles before scoreboard telemetry is checked. Use concise lowercase comment
prose except names, acronyms, and identifiers, with comment blocks before each
logical block. No inferred encryption oracle and no key-loading transaction.


<reference path="tb/spi_operations.svh">
`ifndef SPI_OPERATIONS_SVH
`define SPI_OPERATIONS_SVH

/* include inside a testbench with the named interface signals. */
localparam time HALF_PERIOD_NS = 10000;
localparam time SAMPLE_DELAY_NS = 1;
integer checks = 0;
integer total_pulses = 0;
reg interface_initialized = 1'b0;
reg pulse_active = 1'b0;

/* reject unnamed operations so failures identify their caller. */
task automatic require_name(input string name);
    /* validate the operation label. */
    begin
        /* require a useful test name. */
        if (name.len() == 0) begin
            $display("FAIL arguments empty operation name");
            $fatal(1, "empty operation name");
        end
    end
endtask

/* require initialized, low SCK before changing controls. */
task automatic require_idle_clock(input string name);
    /* reject concurrent clock use and unknown clock state. */
    begin
        require_name(name);
        /* prevent input changes during an active pulse. */
        if (interface_initialized !== 1'b1 || SCK !== 1'b0 ||
                pulse_active !== 1'b0) begin
            $display("FAIL %s interface or clock is not idle", name);
            $fatal(1, "invalid clock ownership");
        end
    end
endtask

/* reject X/Z status before using it for control or checking. */
task automatic require_known_busy(input string name, input reg value);
    /* preserve four-state status checks. */
    begin
        require_name(name);
        /* unknown status must never count as completion. */
        if (value !== 1'b0 && value !== 1'b1) begin
            $display("FAIL %s BUSY is unknown", name);
            $fatal(1, "unknown BUSY");
        end
    end
endtask

/* check status and count exactly one named success. */
task automatic check_busy(input string name, input reg expected);
    /* validate the expectation and observed status. */
    begin
        require_name(name);
        /* reject unknown expected status. */
        if (expected !== 1'b0 && expected !== 1'b1) begin
            $display("FAIL %s expected BUSY is unknown", name);
            $fatal(1, "invalid BUSY expectation");
        end
        require_known_busy(name, BUSY);
        /* fail with a nonzero simulator exit on mismatch. */
        if (BUSY !== expected) begin
            $display("FAIL %s expected_busy=%b actual_busy=%b", name, expected, BUSY);
            $fatal(1, "BUSY mismatch");
        end
        checks = checks + 1;
        $display("PASS %s busy=%b", name, BUSY);
    end
endtask

/* check complete words without allowing matching X/Z bits to pass. */
task automatic check_word32(
    input string name,
    input reg [31:0] actual,
    input reg [31:0] expected
);
    /* validate both words before comparing them. */
    begin
        require_name(name);
        /* reduction XOR detects X/Z in either word. */
        if ((^actual === 1'bx) || (^expected === 1'bx)) begin
            $display("FAIL %s unknown word actual=%h expected=%h", name, actual, expected);
            $fatal(1, "unknown comparison data");
        end
        /* reject unequal known values. */
        if (actual !== expected) begin
            $display("FAIL %s actual=%h expected=%h", name, actual, expected);
            $fatal(1, "word mismatch");
        end
        checks = checks + 1;
        $display("PASS %s value=%h", name, actual);
    end
endtask

/* own every SCK transition after the one-time initialization. */
task automatic sck_pulse(output reg sampled_miso, output reg sampled_busy);
    /* allow setup before rising, then sample registered MISO after NBA settling. */
    begin
        require_idle_clock("sck_pulse");
        /* reject unknown driven control values before a sampling edge. */
        if (^{RST_N, MOSI, NORM_CS_N, START, ENC_DEC} === 1'bx) begin
            $display("FAIL sck_pulse unknown driven control");
            $fatal(1, "unknown interface input");
        end
        pulse_active = 1'b1;
        #(HALF_PERIOD_NS);
        SCK = 1'b1;
        total_pulses = total_pulses + 1;
        #(SAMPLE_DELAY_NS);
        sampled_miso = MISO;
        sampled_busy = BUSY;
        require_known_busy("sck_pulse", sampled_busy);
        #(HALF_PERIOD_NS - SAMPLE_DELAY_NS);
        SCK = 1'b0;
        pulse_active = 1'b0;
    end
endtask

/* initialize once at time zero; MOSI and mode defaults are testbench choices. */
task automatic initialize_interface;
    /* establish deterministic idle signals without emitting a pulse. */
    begin
        /* reject reinitialization instead of resetting clock ownership. */
        if (interface_initialized !== 1'b0 || total_pulses != 0) begin
            $display("FAIL initialize_interface already initialized");
            $fatal(1, "repeated interface initialization");
        end
        SCK = 1'b0;  // time-zero initialization only
        RST_N = 1'b1;
        MOSI = 1'b0;
        NORM_CS_N = 1'b1;
        START = 1'b0;
        ENC_DEC = 1'b0;
        interface_initialized = 1'b1;
    end
endtask

/* change mode only while idle, keeping setup ahead of the next rising edge. */
task automatic set_mode(input reg mode);
    /* reject unknown mode and active transactions. */
    begin
        require_idle_clock("set_mode");
        require_known_busy("set_mode", BUSY);
        /* validate the mode argument and sideband state. */
        if ((mode !== 1'b0 && mode !== 1'b1) ||
                NORM_CS_N !== 1'b1 || START !== 1'b0 || BUSY !== 1'b0) begin
            $display("FAIL set_mode invalid mode or active transaction");
            $fatal(1, "invalid mode change");
        end
        ENC_DEC = mode;  // 0: encrypt; 1: decrypt
    end
endtask

/* clock reset while asserted, then clock once after release. */
task automatic apply_synchronous_reset(input string name);
    reg unused_miso;
    reg sampled_busy;
    /* preserve mode and MOSI while resetting with CS inactive. */
    begin
        require_idle_clock(name);
        NORM_CS_N = 1'b1;
        START = 1'b0;
        RST_N = 1'b0;
        sck_pulse(unused_miso, sampled_busy);
        RST_N = 1'b1;
        sck_pulse(unused_miso, sampled_busy);
        check_busy(name, 1'b0);
    end
endtask

/* transfer all 32 MSB-first bits while capturing simultaneous MISO. */
task automatic transfer_word32(
    input string name,
    input reg [31:0] tx_word,
    output reg [31:0] rx_word
);
    integer bit_index;
    reg sampled_miso;
    reg sampled_busy;
    /* hold CS low across the full word and retain the final MOSI bit. */
    begin
        require_idle_clock(name);
        require_known_busy(name, BUSY);
        /* reject unknown transmit data and overlapping operations. */
        if ((^tx_word === 1'bx) || RST_N !== 1'b1 ||
                NORM_CS_N !== 1'b1 || START !== 1'b0 || BUSY !== 1'b0) begin
            $display("FAIL %s invalid transfer arguments or active core", name);
            $fatal(1, "invalid transfer");
        end
        rx_word = 32'b0;
        NORM_CS_N = 1'b0;
        /* each bit has a low-phase setup and one post-NBA sample. */
        for (bit_index = 31; bit_index >= 0; bit_index = bit_index - 1) begin
            MOSI = tx_word[bit_index];
            sck_pulse(sampled_miso, sampled_busy);
            /* reject unknown data instead of shifting it into a passing word. */
            if (sampled_miso !== 1'b0 && sampled_miso !== 1'b1) begin
                $display("FAIL %s unknown MISO at bit=%0d", name, bit_index);
                $fatal(1, "unknown MISO");
            end
            rx_word[bit_index] = sampled_miso;
        end
        NORM_CS_N = 1'b1;
        $display("TRANSFER %s mosi=%h miso=%h", name, tx_word, rx_word);
    end
endtask

/* pulse START for one full SCK cycle and report operation edge zero. */
task automatic pulse_start(input string operation_name, input reg require_busy_high);
    reg unused_miso;
    reg sampled_busy;
    /* keep CS high and release START only after SCK returns low. */
    begin
        require_idle_clock(operation_name);
        require_known_busy(operation_name, BUSY);
        /* reject unknown policy and an overlapping operation. */
        if ((require_busy_high !== 1'b0 && require_busy_high !== 1'b1) ||
                RST_N !== 1'b1 || NORM_CS_N !== 1'b1 ||
                START !== 1'b0 || BUSY !== 1'b0) begin
            $display("FAIL %s invalid START arguments or active core", operation_name);
            $fatal(1, "invalid START pulse");
        end
        START = 1'b1;
        sck_pulse(unused_miso, sampled_busy);
        START = 1'b0;
        $display("PROCESS %s edge=0 busy=%b", operation_name, sampled_busy);
        /* the supplied application checks this only for encryption. */
        if (require_busy_high === 1'b1) begin
            check_busy({operation_name, ".started"}, 1'b1);
        end
    end
endtask

/* clock processing with either a fixed count or bounded completion polling. */
task automatic clock_until_complete(
    input string operation_name,
    input integer pulse_limit,
    input reg fixed_count,
    output integer pulses_used
);
    reg unused_miso;
    reg sampled_busy;
    /* preserve the replay count even when BUSY falls before its final pulse. */
    begin
        require_idle_clock(operation_name);
        /* reject unknown counts, unbounded limits, and active transfers. */
        if ((^pulse_limit === 1'bx) || pulse_limit < 1 || pulse_limit > 64 ||
                (fixed_count !== 1'b0 && fixed_count !== 1'b1) ||
                RST_N !== 1'b1 || NORM_CS_N !== 1'b1 || START !== 1'b0) begin
            $display("FAIL %s invalid completion arguments", operation_name);
            $fatal(1, "invalid completion request");
        end
        sampled_busy = BUSY;
        require_known_busy(operation_name, sampled_busy);
        pulses_used = 0;
        /* the pulse counter bounds both fixed and completion-driven modes. */
        while (pulses_used < pulse_limit &&
                (fixed_count === 1'b1 || sampled_busy === 1'b1)) begin
            sck_pulse(unused_miso, sampled_busy);
            pulses_used = pulses_used + 1;
            $display("PROCESS %s edge=%0d busy=%b", operation_name, pulses_used, sampled_busy);
        end
        /* report timeout instead of waiting without SCK edges. */
        if (sampled_busy !== 1'b0) begin
            $display("FAIL %s timeout after %0d processing pulses", operation_name, pulse_limit);
            $fatal(1, "completion timeout");
        end
        check_busy({operation_name, ".complete"}, 1'b0);
    end
endtask

/* read output while explicitly shifting the caller's word into MOSI. */
task automatic read_result(
    input string name,
    input reg [31:0] mosi_word,
    output reg [31:0] result
);
    /* reuse the same full-duplex transfer and clock owner. */
    begin
        transfer_word32(name, mosi_word, result);
    end
endtask

`endif

</reference>


<reference path="tb/tb_driver.sv">
`timescale 1ns/1ps

/* test the shared driver against a mock, without recovered circuitry. */
module tb_driver;
    /* use the same processor interface and the same sole SCK owner. */
    reg SCK, RST_N, MOSI, NORM_CS_N, START, ENC_DEC;
    wire MISO, BUSY, ICE_LED;
    reg [31:0] response_word;
    wire [31:0] mock_word, frame_count, frame_bits;
    reg [31:0] received, tx_word, sent_word, random_state;
    reg [31:0] seed = 32'd4313;
    reg sampled_miso, sampled_busy;
    integer index, used_pulses, argument_found;
    string scenario = "normal";
    string argument_text;
    string name;

    /* independently observe wire framing rather than trusting mock telemetry. */
    reg monitor_ready = 1'b0;
    reg monitor_open = 1'b0;
    reg [31:0] monitor_word;
    integer monitor_bits, monitor_frames;

    /* open a passive frame before the next SCK edge. */
    always @(negedge NORM_CS_N) begin
        /* ignore startup before the first synchronous reset. */
        if (monitor_ready === 1'b1) begin
            /* require inactive SCK and a distinct selection edge. */
            if (SCK !== 1'b0 || monitor_open !== 1'b0) begin
                $fatal(1, "DRIVER FAIL monitor.frame_start");
            end
            monitor_open = 1'b1;
            monitor_bits = 0;
            monitor_word = 0;
        end
    end

    /* count actual selected edges and reconstruct MOSI independently. */
    always @(posedge SCK) begin
        /* synchronize observer reset with the peripheral reset. */
        if (RST_N === 1'b0) begin
            monitor_ready = 1'b1;
            monitor_open = 1'b0;
            monitor_bits = 0;
            monitor_frames = 0;
            monitor_word = 0;
        end else if (NORM_CS_N === 1'b0) begin
            /* reject a selected edge without a complete CS frame. */
            if (monitor_open !== 1'b1 || monitor_bits >= 32) begin
                $fatal(1, "DRIVER FAIL monitor.frame_overflow");
            end
            monitor_word = {monitor_word[30:0], MOSI};
            monitor_bits = monitor_bits + 1;
        end
    end

    /* reject premature deassertion and count complete wire frames. */
    always @(posedge NORM_CS_N) begin
        /* startup and inactive reset have no frame to close. */
        if (monitor_ready === 1'b1 && monitor_open === 1'b1) begin
            /* require all bits before closing a low-phase selection. */
            if (SCK !== 1'b0 || monitor_bits != 32) begin
                $fatal(1, "DRIVER FAIL monitor.frame_length bits=%0d", monitor_bits);
            end
            monitor_open = 1'b0;
            monitor_frames = monitor_frames + 1;
            $display("DRIVER FRAME number=%0d bits=%0d mosi=%h", monitor_frames, monitor_bits, monitor_word);
        end
    end

    /* configure mock MISO independently from each transmitted word. */
    spi_mock_peripheral peripheral (
        .SCK(SCK), .RST_N(RST_N), .MOSI(MOSI), .NORM_CS_N(NORM_CS_N),
        .START(START), .ENC_DEC(ENC_DEC), .MISO(MISO), .BUSY(BUSY),
        .ICE_LED(ICE_LED), .RESPONSE_WORD(response_word),
        .RECEIVED_WORD(mock_word), .FRAME_COUNT(frame_count), .FRAME_BITS(frame_bits)
    );
    `include "spi_operations.svh"

    /* reverse all bits only for deliberate driver fault injection. */
    function automatic [31:0] reverse_bits(input reg [31:0] word_value);
        integer bit_index;
        begin
            /* preserve every position while reversing its index. */
            for (bit_index = 0; bit_index < 32; bit_index = bit_index + 1) begin
                reverse_bits[bit_index] = word_value[31-bit_index];
            end
        end
    endfunction

    /* provide directed patterns with unequal high and low bytes. */
    function automatic [31:0] directed_word(input integer slot);
        begin
            /* include boundaries and a single low bit to expose reversed shifts. */
            case (slot)
                0: directed_word = 32'h01234567;
                1: directed_word = 32'h00000000;
                2: directed_word = 32'hffffffff;
                3: directed_word = 32'h80000000;
                4: directed_word = 32'h00000001;
                default: directed_word = 32'h96a50fc3;
            endcase
        end
    endfunction

    /* reject malformed unsigned seeds before narrowing to 32 bits. */
    function automatic [31:0] parse_seed(input string digits);
        reg [63:0] accumulator;
        integer position;
        begin
            accumulator = 0;
            /* bound decimal parsing and reject empty input. */
            if (digits.len() < 1 || digits.len() > 10) begin
                $fatal(1, "DRIVER FAIL invalid seed length");
            end
            /* reject signs, unknowns, and overflow rather than truncating. */
            for (position = 0; position < digits.len(); position = position + 1) begin
                /* accept decimal digits only. */
                if (digits[position] < 48 || digits[position] > 57) begin
                    $fatal(1, "DRIVER FAIL invalid seed digit");
                end
                accumulator = accumulator * 10 + digits[position] - 48;
                /* retain the entire unsigned seed range. */
                if (accumulator > 64'd4294967295) begin
                    $fatal(1, "DRIVER FAIL seed overflow");
                end
            end
            parse_seed = accumulator[31:0];
        end
    endfunction

    /* create malformed selections using the existing pulse owner. */
    task automatic malformed_frame(input integer clocks);
        integer bit_index;
        begin
            NORM_CS_N = 1'b0;
            /* emit a bounded missing, extra, or split frame. */
            for (bit_index = 0; bit_index < clocks; bit_index = bit_index + 1) begin
                MOSI = tx_word[31-(bit_index % 32)];
                sck_pulse(sampled_miso, sampled_busy);
            end
            NORM_CS_N = 1'b1;
            #1;  // allow the framing monitor to report this edge
            $fatal(1, "DRIVER FAIL framing fault escaped mock");
        end
    endtask

    /* bound every run independently of the host process timeout. */
    initial begin
        #20000000;
        $fatal(1, "DRIVER FAIL watchdog exceeded 20 ms");
    end

    /* sequence all stimulus below rising SCK; no background clock is used. */
    initial begin
        $display("DRIVER TEST tb_driver: mock validates harness only, not recovered cryptography");
        $dumpfile("waveforms.vcd");
        $dumpvars(0, tb_driver);
        initialize_interface();
        response_word = 32'hd2963a5c;
        argument_found = $value$plusargs("seed=%s", argument_text);
        /* retain the documented seed when no override is supplied. */
        if (argument_found != 0) begin
            seed = parse_seed(argument_text);
        end
        argument_found = $value$plusargs("scenario=%s", scenario);
        random_state = seed;
        $display("DRIVER TEST configuration seed=%0d scenario=%s", seed, scenario);
        apply_synchronous_reset("driver.reset");
        tx_word = 32'h01234567;

        /* prove the existing scoreboard rejects wrong and unknown expectations. */
        if (scenario == "mismatch") begin
            check_word32("driver.negative.mismatch", 32'h12345678, 32'h12345679);
        end else if (scenario == "unknown_x") begin
            check_word32("driver.negative.unknown_x", 32'hxxxxxxxx, 32'hxxxxxxxx);
        end else if (scenario == "unknown_z") begin
            check_word32("driver.negative.unknown_z", 32'hzzzzzzzz, 32'hzzzzzzzz);
        end else if (scenario == "short_frame") begin
            malformed_frame(31);
        end else if (scenario == "long_frame") begin
            malformed_frame(33);
        end else if (scenario == "split_frame") begin
            malformed_frame(16);
        end else if (scenario == "unknown_miso_x") begin
            response_word = 32'hx2963a5c;
        end else if (scenario == "unknown_miso_z") begin
            response_word = 32'hz2963a5c;
        end else if (scenario != "normal" && scenario != "reverse_tx" &&
                     scenario != "reverse_rx" && scenario != "timeout") begin
            $fatal(1, "DRIVER FAIL unknown scenario");
        end

        /* check six directed patterns and eight reproducible LCG patterns. */
        for (index = 0; index < 14; index = index + 1) begin
            name = $sformatf("driver.frame.%0d", index);
            /* keep golden vectors separate from mock receive state. */
            if (index < 6) begin
                tx_word = directed_word(index);
            end else begin
                random_state = 32'd1664525 * random_state + 32'd1013904223;
                tx_word = random_state;
            end
            /* preserve unknown-response fault injection on the first transfer. */
            if (scenario != "unknown_miso_x" && scenario != "unknown_miso_z") begin
                response_word = 32'hd2963a5c ^ (32'h01020408 * index);
            end
            sent_word = tx_word;
            /* introduce a serial-order defect without changing the expected word. */
            if (scenario == "reverse_tx") begin
                sent_word = reverse_bits(tx_word);
            end
            $display("DRIVER TEST %s tx=%h response=%h", name, tx_word, response_word);
            /* readout must still transmit and update the mock's input register. */
            if (index == 5) begin
                read_result(name, sent_word, received);
            end else begin
                transfer_word32(name, sent_word, received);
            end
            #1;  // settle the independent CS edge monitor before inspecting telemetry
            /* expose reversed read assembly to the unchanged scoreboard. */
            if (scenario == "reverse_rx") begin
                received = reverse_bits(received);
            end
            check_word32({name, ".rx"}, received, response_word);
            check_word32({name, ".tx"}, mock_word, tx_word);
            check_word32({name, ".wire"}, monitor_word, tx_word);
            check_word32({name, ".frames"}, frame_count, index + 1);
            check_word32({name, ".bits"}, frame_bits, 32'd32);
        end

        /* clock while deselected and prove no phantom frame or input shift occurs. */
        MOSI = ~MOSI;
        repeat (3) begin
            sck_pulse(sampled_miso, sampled_busy);
        end
        check_word32("driver.deselected.rx", mock_word, tx_word);
        check_word32("driver.deselected.frames", frame_count, 32'd14);

        /* exercise arbitrary mock completion while continuing to supply SCK. */
        pulse_start("driver.mock_compute", 1'b1);
        /* an intentionally short limit must fail before the mock's completion. */
        if (scenario == "timeout") begin
            clock_until_complete("driver.negative.timeout", 1, 1'b0, used_pulses);
        end else begin
            clock_until_complete("driver.mock_compute", 4, 1'b0, used_pulses);
        end
        /* check exact pulse and scoreboard counts before declaring driver success. */
        if (used_pulses != 3 || checks != 75 || total_pulses != 457 || monitor_frames != 14) begin
            $fatal(1, "DRIVER FAIL unexpected accounting checks=%0d pulses=%0d", checks, total_pulses);
        end
        $display("DRIVER SUMMARY PASS checks=%0d frames=%0d total_pulses=%0d seed=%0d",
            checks, frame_count, total_pulses, seed);
        $finish;
    end
endmodule

